func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}}
	// The coupon's percentage replaces the subscription's discount: 25% of 5499 is 1374.75 -> 1375.
	percent := Compute(store.Invoice{Lines: lines, DiscountPercent: 10, Coupon: "PCT25", CouponPercentOff: 25, TaxRateBP: 825})
	if want := (Totals{Subtotal: 5499, Discount: 1375, Tax: 343, Total: 4467}); percent != want {
		t.Fatalf("percent coupon = %+v, want %+v", percent, want)
	}
	// An amount off takes that amount off the subtotal.
	amount := Compute(store.Invoice{Lines: lines, Coupon: "FIVE", CouponAmountOff: 500})
	if amount.Discount != 500 || amount.Total != 4999 {
		t.Fatalf("amount coupon = %+v", amount)
	}
	// It is never more than the subtotal.
	capped := Compute(store.Invoice{Lines: lines, Coupon: "BIG", CouponAmountOff: 100000})
	if capped.Discount != 5499 || capped.Total != 0 {
		t.Fatalf("capped amount coupon = %+v", capped)
	}
}

